// Host-only fixture for the actual Android HPKE and request-proof primitives.
// The signing key is generated by the Node verifier; no device key is used.
#include "../android/app/src/main/cpp/spdecode_hpke.h"
#include "../android/app/src/main/cpp/spdecode_security.h"
#include <algorithm>
#include <array>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

namespace {
using Bytes=std::vector<unsigned char>;
Bytes unhex(const std::string& text){
    if(text.size()%2)throw std::runtime_error("INVALID_HEX");
    auto digit=[](char c)->unsigned{
        if(c>='0'&&c<='9')return unsigned(c-'0');
        if(c>='a'&&c<='f')return unsigned(c-'a'+10);
        throw std::runtime_error("INVALID_HEX");
    };
    Bytes out;
    for(std::size_t i=0;i<text.size();i+=2)
        out.push_back(static_cast<unsigned char>((digit(text[i])<<4)|digit(text[i+1])));
    return out;
}
std::string hex(const Bytes& bytes){
    const char* alphabet="0123456789abcdef";
    std::string out;
    for(auto c:bytes){out.push_back(alphabet[c>>4]);out.push_back(alphabet[c&15]);}
    return out;
}
}
int main(int argc,char** argv){
    try{
        if(argc!=5)throw std::runtime_error("usage: fixture operation publicPinHex metadataJson attachmentHex");
        const int op=std::stoi(argv[1]);
        const auto pinBytes=unhex(argv[2]);
        if(pinBytes.size()!=40)throw std::runtime_error("INVALID_PIN");
        std::array<unsigned char,40> pin{};
        std::copy(pinBytes.begin(),pinBytes.end(),pin.begin());
        const std::string metadata=argv[3];
        auto prepared=spdecode::hpkePrepare(op,Bytes(metadata.begin(),metadata.end()),unhex(argv[4]),pin);
        const std::string bearer="fixture.session";
        const auto proof=spdecode::formatProof(op,"1.1.29",prepared.wire.data(),prepared.wire.size(),
            bearer,"1793380000",std::string(32,'A'));
        spdecode::ActionBinding action;
        if(op==26||op==28)
            action=spdecode::inlineActionBinding(op,bearer,prepared.wire.data(),prepared.wire.size());
        std::cout<<hex(prepared.wire)<<'\n'<<hex(Bytes(proof.begin(),proof.end()))<<'\n'
            <<(action.id.empty()?"-":action.id)<<'\n'
            <<(action.requestHash.empty()?"-":action.requestHash)<<std::endl;
        std::string reply;std::getline(std::cin,reply);
        const auto clear=spdecode::hpkeOpen(prepared.handle,200,prepared.wire,unhex(reply));
        std::cout<<hex(clear)<<std::endl;
        return 0;
    }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}
}
